fn remove_element(s: &Vec<i32>, k: usize) -> Vec<i32> {
    // Preallocate a new vector of the correct size
    let mut v = Vec::with_capacity(s.len() - 1);

    // Copy elements before index k
    v.extend_from_slice(&s[..k]);

    // Copy elements after index k
    v.extend_from_slice(&s[k + 1..]);

    v
}

